mapper.select:
SELECT S.ChnlCode, S.StoreCode, S.StoreName, S.StoreDesc, S.ParentStoreCode, S.StoreLevel, S.StoreSeq, S.AdultYn, S.TmplCode, S.State, S.Remark, S.RegistDate, S.RegistId, S.RegistName, S.ChangeDate, S.ChangeId, S.ChangeName, (SELECT COUNT(*) FROM shopion.tStrStore C WHERE C.ChnlCode = S.ChnlCode AND C.ParentStoreCode = S.StoreCode) AS ChildCount FROM shopion.tStrStore S
AND S.ChnlCode = #{pChnlCode}
AND S.ParentStoreCode = #{pParentStoreCode}
AND S.StoreLevel = 0
AND NOT EXISTS ( SELECT 1 FROM shopion.tStrStore CS WHERE CS.ChnlCode = S.ChnlCode AND CS.ParentStoreCode = S.StoreCode )
ORDER BY S.StoreSeq

SELECT MAX(StoreCode)
FROM shopion.tStrStore


        AND ChnlCode = #{pChnlCode}


        AND ParentStoreCode = #{pParentStoreCode}

SELECT S3.ChnlCode, S3.StoreCode, S3.StoreName, S3.StoreDesc, S3.ParentStoreCode, S3.StoreLevel, S3.StoreSeq, S3.AdultYn, S3.TmplCode, S3.State, S0.StoreCode AS StoreCode1, S0.StoreName AS StoreName1, S1.StoreCode AS StoreCode2, S1.StoreName AS StoreName2, S2.StoreCode AS StoreCode3, S2.StoreName AS StoreName3, S3.StoreCode AS StoreCode4, S3.StoreName AS StoreName4 FROM shopion.tStrStore S3 LEFT JOIN shopion.tStrStore S2 ON S3.ChnlCode = S2.ChnlCode AND S3.ParentStoreCode = S2.StoreCode LEFT JOIN shopion.tStrStore S1 ON S2.ChnlCode = S1.ChnlCode AND S2.ParentStoreCode = S1.StoreCode LEFT JOIN shopion.tStrStore S0 ON S1.ChnlCode = S0.ChnlCode AND S1.ParentStoreCode = S0.StoreCode
AND S3.ChnlCode = #{pChnlCode}
ORDER BY S3.StoreLevel, S3.StoreSeq

SELECT ChnlCode, StoreCode, StoreName, StoreDesc, ParentStoreCode,
       StoreLevel, StoreSeq, AdultYn, TmplCode, State, Remark,
       RegistDate, RegistId, RegistName, ChangeDate, ChangeId, ChangeName
FROM shopion.tStrStore
WHERE ChnlCode = #{pChnlCode}
  AND StoreCode = #{pStoreCode}

SELECT ChnlCode, StoreCode, StoreName, StoreDesc, ParentStoreCode, StoreLevel, StoreSeq, AdultYn, TmplCode, State, Remark, RegistDate, RegistId, RegistName, ChangeDate, ChangeId, ChangeName FROM shopion.tStrStore
AND ChnlCode = #{pChnlCode}
AND StoreLevel = #{pStoreLevel}
ORDER BY StoreLevel, StoreSeq

mapper.insert:
INSERT INTO shopion.tStrStore (
    ChnlCode, StoreCode, StoreName, StoreDesc, ParentStoreCode,
    StoreLevel, StoreSeq, AdultYn, TmplCode, State, Remark,
    RegistDate, RegistId, RegistName, ChangeDate, ChangeId, ChangeName
) VALUES (
    #{chnlCode}, #{storeCode}, #{storeName}, #{storeDesc}, #{parentStoreCode},
    #{storeLevel}, #{storeSeq}, #{adultYn}, #{tmplCode}, #{state}, #{remark},
    #{registDate}, #{registId}, #{registName}, #{changeDate}, #{changeId}, #{changeName}
)

mapper.delete:
DELETE FROM shopion.tStrStore
WHERE ChnlCode = #{pChnlCode}
  AND StoreCode = #{pStoreCode}
